template.script:
(function(){
  function init(){
    var modal = document.getElementById('certModal');
    if(!modal) return;
    var frame = document.getElementById('certFrame');
    var dl = document.getElementById('certDownload');
    function open(url){
      if(!url) return;
      frame.src = url;
      dl.href = url + (url.indexOf('?') >= 0 ? '&' : '?') + 'download=1';
      modal.classList.add('open');
    }
    function close(){ modal.classList.remove('open'); frame.src = 'about:blank'; }
    document.querySelectorAll('.js-cert-view').forEach(function(b){
      b.addEventListener('click', function(){ open(b.getAttribute('data-url')); });
    });
    var c = document.getElementById('certClose');
    if(c){ c.addEventListener('click', close); }
    modal.addEventListener('click', function(ev){ if(ev.target === modal){ close(); } });
    document.addEventListener('keydown', function(ev){ if(ev.key === 'Escape'){ close(); } });
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', init); } else { init(); }
})();

aside.script:
(function () {
    var sel = document.getElementById('fltSizeGrade');
    if (!sel) { return; }
    var radios = document.querySelectorAll('input[name="presentation"]');
    function currentPres() {
        for (var i = 0; i < radios.length; i++) {
            if (radios[i].checked) { return radios[i].value; }
        }
        return '';
    }
    function syncTallas() {
        var pres = currentPres();
        var opts = sel.options;
        for (var i = 0; i < opts.length; i++) {
            var op = opts[i];
            if (!op.value) { op.hidden = false; continue; }
            var match = !pres || op.getAttribute('data-presentation') === pres;
            op.hidden = !match;
            op.disabled = !match;
            if (!match && op.selected) { sel.value = ''; }
        }
    }
    for (var i = 0; i < radios.length; i++) {
        radios[i].addEventListener('change', syncTallas);
    }
    syncTallas();
})();

t.script:
(function(){
  function init(){
    var btn = document.getElementById("loadMoreBtn");
    var wrap = document.getElementById("loadMoreWrap");
    var grid = document.getElementById("prodGrid");
    if(!btn || !wrap || !grid) return;
    var loading = false;
    btn.addEventListener("click", function(){
      if(loading) return;
      loading = true;
      var original = btn.innerHTML;
      btn.innerHTML = '<i class="fa fa-spinner fa-spin me-1"></i> Cargando…';
      btn.disabled = true;
      var params = new URLSearchParams();
      params.set("offset", wrap.getAttribute("data-next-offset") || "0");
      ["sort","q","stage","species","presentation","size_grade","location","seller","price_min","price_max"].forEach(function(k){
        var v = grid.getAttribute("data-" + k);
        if(v) params.set(k, v);
      });
      fetch("/marketplace/cards?" + params.toString(), {
        headers: {"X-Requested-With": "XMLHttpRequest"}
      }).then(function(r){ return r.json(); }).then(function(data){
        // Inserta las nuevas tarjetas SIN mover el scroll.
        var tmp = document.createElement("div");
        tmp.innerHTML = data.html;
        while(tmp.firstChild){ grid.appendChild(tmp.firstChild); }
        wrap.setAttribute("data-next-offset", data.next_offset);
        var shown = document.getElementById("shownCount");
        if(shown){ shown.textContent = data.shown_count; }
        if(data.has_more){
          btn.innerHTML = original;
          btn.disabled = false;
          loading = false;
        } else {
          btn.remove();
        }
      }).catch(function(){
        btn.innerHTML = original;
        btn.disabled = false;
        loading = false;
      });
    });
  }
  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", init);
  } else { init(); }
})();

div.script:
(function(){
  function init(){
    var main = document.getElementById('buyMainImg');
    var thumbs = document.querySelectorAll('.js-buy-thumb');
    if(!main || !thumbs.length) return;
    thumbs.forEach(function(t){
      t.addEventListener('click', function(){
        main.src = t.getAttribute('data-src');
        thumbs.forEach(function(x){ x.classList.remove('is-active'); });
        t.classList.add('is-active');
      });
    });
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', init); } else { init(); }
})();

(function(){
    var form = document.getElementById('buyForm');
    if(!form){ return; }
    form.addEventListener('submit', function(ev){
        if(form.dataset.paid === '1'){ return; }
        ev.preventDefault();
        var qtyEl = document.getElementById('qty_hidden_buy');
        var qty = parseFloat((qtyEl && qtyEl.value) || '0');
        if(!qty || qty <= 0){ alert('Ingresa una cantidad válida antes de pagar.'); return; }
        var overlay = document.getElementById('payOverlay');
        var countEl = document.getElementById('payCount');
        var btn = document.getElementById('btn_buy');
        if(btn){ btn.disabled = true; }
        if(overlay){ overlay.style.display = 'flex'; }
        var left = 20;
        var timer = setInterval(function(){
            left -= 1;
            if(countEl){ countEl.textContent = left; }
            if(left <= 0){
                clearInterval(timer);
                form.dataset.paid = '1';
                form.submit();
            }
        }, 1000);
    });
})();

(function(){
  var btn = document.getElementById('btn_check');
  var form = document.getElementById('checkForm');
  var modal = document.getElementById('chkModal');
  if(!btn || !form || !modal) return;
  var priceEl = document.getElementById('unit_price');
  var availEl = document.getElementById('available_qty');
  var qtyInput = document.getElementById('qty_input');
  var price = parseFloat((priceEl && priceEl.dataset.price) || '0') || 0;
  var avail = parseFloat((availEl && availEl.dataset.available) || '0') || 0;
  var fee = parseFloat(form.dataset.fee || '0') || 0;
  function fmt(n){ return (isNaN(n) ? 0 : n).toFixed(2); }
  btn.addEventListener('click', function(){
    var qty = parseFloat((qtyInput && qtyInput.value) || '0') || 0;
    if(!qty || qty <= 0){ alert('Ingresa una cantidad válida antes de solicitar el chequeo.'); return; }
    if(qty > avail){ alert('La cantidad supera lo disponible.'); return; }
    document.getElementById('chkQty').textContent = qty;
    document.getElementById('chkProd').textContent = fmt(qty * price);
    document.getElementById('chkFee').textContent = fmt(fee);
    document.getElementById('chkTotal').textContent = fmt(qty * price + fee);
    document.getElementById('qty_hidden_check').value = qty;
    modal.classList.add('open');
  });
  var cancel = document.getElementById('chkCancel');
  if(cancel){ cancel.addEventListener('click', function(){ modal.classList.remove('open'); }); }
  modal.addEventListener('click', function(ev){ if(ev.target === modal){ modal.classList.remove('open'); } });
  var pay = document.getElementById('chkPay');
  if(pay){
    pay.addEventListener('click', function(){
      if(form.dataset.paid === '1'){ return; }
      modal.classList.remove('open');
      var overlay = document.getElementById('payOverlay');
      var countEl = document.getElementById('payCount');
      if(overlay){ overlay.style.display = 'flex'; }
      var left = 20;
      var timer = setInterval(function(){
        left -= 1;
        if(countEl){ countEl.textContent = left; }
        if(left <= 0){
          clearInterval(timer);
          form.dataset.paid = '1';
          form.submit();
        }
      }, 1000);
    });
  }
})();


(function () {
const qtyInput = document.getElementById('qty_input');
const qtyHiddenBuy = document.getElementById('qty_hidden_buy');
const qtyHiddenCheck = document.getElementById('qty_hidden_check');
const unitPriceEl = document.getElementById('unit_price');
const availableEl = document.getElementById('available_qty');
const totalEl = document.getElementById('total_value');
const errEl = document.getElementById('qty_error');
const zeroErrEl = document.getElementById('qty_zero_error');
const btnBuy = document.getElementById('btn_buy');
const btnCheck = document.getElementById('btn_check');

if (!qtyInput || !unitPriceEl || !availableEl || !totalEl || !btnBuy || !btnCheck) return;

const price = parseFloat(unitPriceEl.dataset.price || "0") || 0;
const available = parseFloat(availableEl.dataset.available || "0") || 0;

function fmt(n) {
    const v = (isNaN(n) ? 0 : n);
    return v.toFixed(2);
}

function recalc() {
    const qty = parseFloat(qtyInput.value || "0") || 0;

    if (qtyHiddenBuy) qtyHiddenBuy.value = qty;
    if (qtyHiddenCheck) qtyHiddenCheck.value = qty;

    const over = qty > available;
    const zero = qty <= 0;

    totalEl.textContent = fmt(qty * price);

    if (errEl) errEl.classList.toggle('d-none', !over);
    if (zeroErrEl) zeroErrEl.classList.toggle('d-none', !zero);

    if (over || zero) {
    btnBuy.setAttribute('disabled', 'disabled');
    btnCheck.setAttribute('disabled', 'disabled');
    } else {
    btnBuy.removeAttribute('disabled');
    btnCheck.removeAttribute('disabled');
    }
}

qtyInput.addEventListener('input', recalc);
recalc();
})();


(function () {

  function pad2(n){ return String(n).padStart(2,'0'); }
  function ymd(d){
    return d.getFullYear() + "-" + pad2(d.getMonth()+1) + "-" + pad2(d.getDate());
  }
  function monthTitle(d){
    const months = ["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];
    return months[d.getMonth()] + " " + d.getFullYear();
  }

  async function loadEvents() {
    const payload = {
      jsonrpc: "2.0",
      method: "call",
      params: {},
      id: Date.now(),
    };

    const r = await fetch("/marketplace/calendar/events", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      credentials: "same-origin",
    });

    const data = await r.json();
    if (data.error) {
      throw new Error(data.error.data?.message || data.error.message || "Error RPC");
    }
    return data.result || [];
  }


  function showMsg(html, kind){
    const box = document.getElementById("calMsg");
    box.classList.remove("d-none");
    box.innerHTML =
      '<div class="alert alert-' + (kind || 'warning') + ' py-2 mb-0" style="border-radius:14px;">' +
      html + '</div>';
  }

  function buildIndex(events){
    const byDate = {};
    (events || []).forEach(e => {
      const d = (e.start || "").slice(0,10);
      if (!d) return;
      byDate[d] = byDate[d] || [];
      byDate[d].push(e);
    });
    return byDate;
  }

  function renderMonth(viewDate, byDate){
    const grid = document.getElementById("calGrid");
    const title = document.getElementById("calTitle");
    grid.innerHTML = "";
    title.textContent = monthTitle(viewDate);

    // calendario Lunes=0 ... Domingo=6
    const first = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1);
    const last  = new Date(viewDate.getFullYear(), viewDate.getMonth()+1, 0);

    // convertir JS getDay (Dom=0) a (Lun=0)
    const firstDow = (first.getDay() + 6) % 7;
    const daysInMonth = last.getDate();

    const totalCells = Math.ceil((firstDow + daysInMonth)/7) * 7;

    const todayStr = ymd(new Date());

    for (let cell=0; cell<totalCells; cell++){
      const dayNum = cell - firstDow + 1;
      const inMonth = dayNum >= 1 && dayNum <= daysInMonth;

      const cellDate = new Date(viewDate.getFullYear(), viewDate.getMonth(), dayNum);
      const dateStr = inMonth ? ymd(cellDate) : "";

      const wrap = document.createElement("div");
      wrap.className = "p-2";
      wrap.style.minHeight = "110px";
      wrap.style.borderRight = "1px solid rgba(0,0,0,.06)";
      wrap.style.borderBottom = "1px solid rgba(0,0,0,.06)";
      wrap.style.background = inMonth ? "#fff" : "rgba(0,0,0,.015)";

      // marcador hoy
      if (inMonth && dateStr === todayStr){
        wrap.style.boxShadow = "inset 0 0 0 2px rgba(18,62,92,.25)";
        wrap.style.borderRadius = "10px";
      }

      if (!inMonth){
        grid.appendChild(wrap);
        continue;
      }

      const header = document.createElement("div");
      header.className = "d-flex justify-content-between align-items-center mb-1";
      header.innerHTML =
        '<div style="font-weight:900; font-size:13px;">' + dayNum + '</div>';

      const items = byDate[dateStr] || [];
      if (items.length){
        const badge = document.createElement("span");
        badge.className = "badge rounded-pill text-bg-light border";
        badge.style.fontWeight = "900";
        badge.textContent = items.length;
        header.appendChild(badge);
      }

      wrap.appendChild(header);

      // lista eventos (máx 3 + "ver más")
      const list = document.createElement("div");
      list.className = "d-grid gap-1";

      const maxShow = 3;
      items.slice(0, maxShow).forEach(ev => {
        const a = document.createElement("a");
        a.href = ev.url || "#";
        a.className = "text-decoration-none";
        a.style.display = "block";

        a.innerHTML =
          '<div class="px-2 py-1 rounded-3" ' +
            'style="border:1px solid rgba(18,62,92,.12); background:rgba(18,62,92,.06); font-size:12px;">' +
            '<div style="font-weight:900; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">' +
              (ev.meta?.name || ev.title || 'Producto') +
            '</div>' +
            '<div class="text-muted" style="white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">' +
              (ev.meta?.stage ? (ev.meta.stage + ' • ') : '') +
              (ev.meta?.seller || '') +
            '</div>' +
          '</div>';

        list.appendChild(a);
      });

      if (items.length > maxShow){
        const more = document.createElement("div");
        more.className = "text-muted";
        more.style.fontSize = "12px";
        more.textContent = "+" + (items.length - maxShow) + " más";
        list.appendChild(more);
      }

      wrap.appendChild(list);
      grid.appendChild(wrap);
    }
  }

  function renderList(byDate){
    const host = document.getElementById("calListView");
    host.innerHTML = "";
    const dates = Object.keys(byDate).sort();
    if(!dates.length){ return; }
    dates.forEach(function(d){
      const items = byDate[d];
      const sec = document.createElement("div");
      sec.className = "mb-3";
      let html = '<div class="s-filter-sec-label" style="margin-bottom:8px;"><i class="fa fa-calendar"></i> ' + d + ' · ' + items.length + ' producto(s)</div>';
      items.forEach(function(ev){
        const m = ev.meta || {};
        html +=
          '<a href="' + (ev.url || '#') + '" class="mp-table-card" style="display:flex; justify-content:space-between; gap:12px; align-items:center; padding:12px 16px; margin-bottom:8px; text-decoration:none;">' +
            '<div style="min-width:0;">' +
              '<div style="font-weight:800; color:var(--shrimp-ink);">' + (m.name || ev.title || 'Producto') + '</div>' +
              '<div class="text-faint" style="font-size:13px;">' + (m.stage ? (m.stage + ' • ') : '') + (m.seller || '') + (m.location ? (' • ' + m.location) : '') + '</div>' +
            '</div>' +
            '<div class="text-end" style="white-space:nowrap;">' +
              '<div style="font-weight:800;">' + (m.qty != null ? m.qty : '') + ' ' + (m.uom || '') + '</div>' +
              '<div class="text-faint" style="font-size:13px;">' + (m.price != null ? ('$' + m.price) : '') + '</div>' +
            '</div>' +
          '</a>';
      });
      sec.innerHTML = html;
      host.appendChild(sec);
    });
  }

  function setupViewToggle(){
    const vc = document.getElementById("viewCal");
    const vl = document.getElementById("viewList");
    const calView = document.getElementById("calCalView");
    const listView = document.getElementById("calListView");
    const nav = document.getElementById("calNav");
    function setView(cal){
      calView.classList.toggle("d-none", !cal);
      listView.classList.toggle("d-none", cal);
      nav.style.display = cal ? "" : "none";
      vc.classList.toggle("s-btn-primary", cal); vc.classList.toggle("s-btn-ghost", !cal);
      vl.classList.toggle("s-btn-primary", !cal); vl.classList.toggle("s-btn-ghost", cal);
    }
    vc.addEventListener("click", function(){ setView(true); });
    vl.addEventListener("click", function(){ setView(false); });
  }

  document.addEventListener("DOMContentLoaded", async function () {
    let viewDate = new Date();
    viewDate = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1);

    try {
      const events = await loadEvents();
      const byDate = buildIndex(events);

      if (!events || !events.length){
        showMsg("No hay productos publicados con <b>fecha tentativa de entrega</b> (expected_delivery_date).", "info");
      }

      renderMonth(viewDate, byDate);
      renderList(byDate);
      setupViewToggle();

      document.getElementById("calPrev").addEventListener("click", () => {
        viewDate = new Date(viewDate.getFullYear(), viewDate.getMonth()-1, 1);
        renderMonth(viewDate, byDate);
      });
      document.getElementById("calNext").addEventListener("click", () => {
        viewDate = new Date(viewDate.getFullYear(), viewDate.getMonth()+1, 1);
        renderMonth(viewDate, byDate);
      });
      document.getElementById("calToday").addEventListener("click", () => {
        const now = new Date();
        viewDate = new Date(now.getFullYear(), now.getMonth(), 1);
        renderMonth(viewDate, byDate);
      });

    } catch (e) {
      console.error(e);
      showMsg("No se pudieron cargar los eventos del calendario. Revisa el endpoint <code>/marketplace/calendar/events</code>.", "danger");
    }
  });

})();
